import StatusBadge from '../../components/StatusBadge';
import type { TaskSummary } from '../../types/query';
export default function TaskDetail({ task }: { task: TaskSummary }) { return <section className="detail-panel" aria-labelledby="task-title"><div className="detail-header"><div><p className="eyebrow">Task</p><h2 id="task-title">{task.title}</h2></div><StatusBadge status={task.status} /></div><dl className="detail-grid"><div><dt>Owner</dt><dd>{task.owner}</dd></div><div><dt>Priority</dt><dd>{task.priority}</dd></div><div><dt>Due</dt><dd>{new Date(task.due_at).toLocaleString()}</dd></div><div><dt>Version</dt><dd>{task.version}</dd></div><div><dt>Mission</dt><dd className="mono">{task.mission_id}</dd></div><div><dt>Updated</dt><dd>{new Date(task.updated_at).toLocaleString()}</dd></div></dl><div className="read-only-note"><strong>Read-only web scope</strong><span>Task lifecycle and ownership changes require a native client.</span></div></section>; }
