import { useEffect, useMemo, useState } from 'react';
import { useOnyxQuery } from '../../hooks/useQuery';
import type { TaskSummary } from '../../types/query';
import TaskList from './TaskList';
import TaskDetail from './TaskDetail';

export default function TasksPage() { const query = useOnyxQuery<TaskSummary>('task.list'); const [selected, setSelected] = useState<TaskSummary | null>(null); const [status, setStatus] = useState('all'); const filtered = useMemo(() => query.data?.data.filter((task) => status === 'all' || task.status === status) ?? [], [query.data, status]); useEffect(() => { if (!selected && filtered[0]) setSelected(filtered[0]); }, [filtered, selected]); return <div className="page-stack"><header className="page-header"><div><p className="eyebrow">Execution visibility</p><h1>Tasks</h1><p>Inspect operational work without introducing client-side lifecycle logic.</p></div><label className="filter-label">Status<select value={status} onChange={(e) => { setStatus(e.target.value); setSelected(null); }}><option value="all">All</option><option value="active">Active</option><option value="blocked">Blocked</option><option value="paused">Paused</option></select></label></header><div className="master-detail"><section className="panel"><div className="panel-heading"><h2>Work queue</h2><span>{filtered.length} shown</span></div>{query.isLoading ? <div className="skeleton-list" /> : <TaskList tasks={filtered} selectedId={selected?.id ?? null} onSelect={setSelected} />}</section>{selected ? <TaskDetail task={selected} /> : <div className="detail-panel empty-state"><h2>Select a task</h2></div>}</div></div>; }
